/* §3.8 / §20.5.17 JavaLetter: a Unicode letter, or '_' or '$'. */
static inline bool juni_is_java_letter(int cp) {
    return juni_is_letter(cp) || cp == '_' || cp == '$';
}

/* §3.8 / §20.5.18 JavaLetterOrDigit: a Java letter, or a Unicode digit. */
static inline bool juni_is_java_letter_or_digit(int cp) {
    return juni_is_java_letter(cp) || juni_is_digit(cp);
}

